arguments.command:
cd /workspace && python3 - << 'EOF'
import json, sys
sys.path.insert(0,'/workspace/submission')
from protocol import parse_request, Invalid
data = open('/workspace/tmp/tests/stressB.json','rb').read()
try:
    out = parse_request(data)
    print("parsed ok")
except Invalid as e:
    print("parse Invalid:", e)
# find offending addresses
d = json.loads(data)
import ipaddress
for ci, case in enumerate(d['cases']):
    for bi, b in enumerate(case['bursts']):
        for a in b['addresses']:
            try:
                ipaddress.IPv6Address(a)
            except ValueError:
                print('bad addr', ci, bi, repr(a))
                raise SystemExit
print('addresses ok')
EOF
